-- Modify "kyc_applications" table
ALTER TABLE "seller"."kyc_applications" DROP CONSTRAINT "kyc_applications_complete_check", ADD CONSTRAINT "kyc_applications_complete_check" CHECK ((status <> ALL (ARRAY['SUBMITTED'::text, 'APPROVED'::text, 'REJECTED'::text])) OR ((submitted_at IS NOT NULL) AND ((pii_purged_at IS NOT NULL) OR ((real_name IS NOT NULL) AND (english_name IS NOT NULL) AND (bank_name IS NOT NULL) AND (bank_code IS NOT NULL) AND (bank_account_enc IS NOT NULL) AND (payout_contact_email IS NOT NULL) AND (((seller_type = 'INDIVIDUAL'::text) AND (id_card_no_enc IS NOT NULL)) OR ((seller_type = 'COMPANY'::text) AND (company_name IS NOT NULL) AND (tax_id IS NOT NULL) AND (rep_id_card_no_enc IS NOT NULL)))))));
